export function Pending({
  isPending = {{isPending}},
  action = "{{action}}",
  duration = {{duration}},
  accent = "{{accent}}",
}) {
  const verb = action === "submit" ? "Submit" : "Upload";
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa" }}>
      <button type="button" disabled={isPending} style={{ display: "inline-flex", alignItems: "center", gap: 8, fontWeight: 600, border: "none", borderRadius: 8, padding: "9px 16px", background: accent, color: "#241430", cursor: isPending ? "progress" : "pointer", opacity: isPending ? .8 : 1 }}>
        {isPending && <span className="spin" style={{ width: 13, height: 13, border: "2px solid #24143044", borderTopColor: "#241430", borderRadius: 999, display: "inline-block" }} />}
        <span>{isPending ? `${verb}ting\u2026` : verb}</span>
      </button>
      <p role="status" aria-live="polite" style={{ margin: "10px 0 0", fontSize: 12 }}>{isPending ? "Started, not yet finished" : "Idle, ready to start"}</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .spin { animation: lod-pnd-spin ${duration}ms linear infinite; }
          @keyframes lod-pnd-spin { to { transform: rotate(360deg); } }
        }
      `}</style>
    </div>
  );
}
